+/**
+ * Variance per item between two days (inclusive): the theoretical use from
+ * the sales sold in those days, the actual use (every consume movement in
+ * those days) and the difference (actual minus theoretical).
+ */
+export function varianceReport(store, from, to) {
+  if (from > to) throw new AppError("bad_request", { reason: "from must not be after to" });
+  const round = (n) => Math.round(n * 1000) / 1000;
+  const theoretical = theoreticalUse(store, from, to);
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  const actual = new Map();
