--- /dev/null
+++ b/src/domain/sales.js
@@ -0,0 +1,72 @@
+// Sales from the till. Each line is a dish sold `qty` times; a dish uses one
+// portion of its recipe per sale. Recording sales consumes the ingredients
+// (ledger ref `sale:<ticket>`, at the time of the sale) and is all or nothing.
+import { AppError } from "../errors.js";
+import { dayOf } from "../dates.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+// Ingredient quantities one sale line uses (zero quantities left out).
+function lineUse(store, line) {
+  const recipe = getRecipe(store, getDish(store, line.dishId).recipeId);
+  return scaled(recipe, line.qty).filter((n) => n.qty > 0);
+}
+
+/** True when a ticket has been imported before. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sale lines { row, ticket, soldAt, dishId, qty } and consumes their
+ * ingredients. Tickets already recorded are skipped. If an item runs out,
+ * nothing is recorded and sale_out_of_stock names the line's row. Returns
+ * { tickets, dishes }: tickets recorded and portions sold on them.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const uses = fresh.map((l) => lineUse(store, l));
+  const sales = (store.data.sales ??= []);
+  // What to put back if a line fails part-way.
+  const before = {
+    qty: new Map(store.data.batches.map((b) => [b.id, b.qty])),
+    movements: store.data.movements.length,
+    sales: sales.length,
+    seq: { ...store.data.seq },
+  };
+  try {
+    fresh.forEach((line, i) => {
+      for (const n of uses[i]) {
+        try {
+          consume(store, n.itemId, n.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+        } catch (e) {
+          if (!(e instanceof AppError) || e.code !== "not_enough_stock") throw e;
+          throw new AppError("sale_out_of_stock", { ...e.params, row: line.row });
+        }
+      }
+      sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty });
+    });
+  } catch (e) {
+    for (const b of store.data.batches) b.qty = before.qty.get(b.id);
+    store.data.movements.length = before.movements;
+    sales.length = before.sales;
+    store.data.seq = before.seq;
+    throw e;
+  }
+  return {
+    tickets: new Set(fresh.map((l) => l.ticket)).size,
+    dishes: fresh.reduce((s, l) => s + l.qty, 0),
+  };
+}
+
+/** Quantity per item (a Map) that the sales sold from `from` to `to` (inclusive days) should have used. */
+export function theoreticalUse(store, from, to) {
+  const byItem = new Map();
+  for (const sale of store.data.sales ?? []) {
+    const day = dayOf(sale.soldAt);
+    if (day < from || day > to) continue;
+    for (const n of lineUse(store, sale)) byItem.set(n.itemId, (byItem.get(n.itemId) ?? 0) + n.qty);
+  }
+  return byItem;
+}
